"""Real native per-attempt directory admission, host ACK and report provenance."""
import argparse,json,pathlib,subprocess,tempfile,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--executable',required=True);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);p.add_argument('--directory',required=True,type=pathlib.Path);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
common='import{defineNativeSuite}from '+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{existsSync,statSync,writeFileSync,readFileSync}from'node:fs';import{setTimeout as wait}from'node:timers/promises';"
def run(name,source,code=0,workers=1,broken=False):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+'\n'+source)
 if broken:(root/'test-results').write_text('actual regular file prevents native root mkdir')
 v=subprocess.run([a.executable,'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html'),'--workers',str(workers)],capture_output=True,timeout=18);(root/'stdout.bin').write_bytes(v.stdout);(root/'stderr.bin').write_bytes(v.stderr);assert v.returncode==code and not v.stderr,(name,v.returncode,v.stdout,v.stderr)
 r=json.loads((root/'actual.json').read_text());props={x.attrib['name']:x.attrib.get('value','')for x in ET.parse(root/'actual.xml').findall('.//property')};html=(root/'actual.html').read_text()
 assert len(r['outputs'])==len(r['attempts']) and len({o['id']for o in r['outputs']})==len(r['outputs']) and len({o['proposedPath']for o in r['outputs']})==len(r['outputs'])
 for o in r['outputs']:
  assert any(all(t[k]==o[k]for k in ['testId','generation','workerIndex','pid'])for t in r['attempts']);assert o['writerPid']!=o['pid'] and o['writerExitReceiptMonotonicMs']<=o['physicalReceiptMonotonicMs'];prefix='native.output'+o['id']+'.';assert props[prefix+'generation']==o['generation'] and props[prefix+'status']==o['status'];assert 'Native attempt output directories'in html
  if 'outputDir'in o:
   actual=pathlib.Path(o['outputDir']);assert o['status']=='ready'and o['readyReceipt']and not o['writerSignaled']and o['writerExitCode']==0 and actual.is_dir()and str(actual.stat().st_ino)==o['inode']and actual.stat().st_dev==o['device']and o['physicalReceiptMonotonicMs']<=o['assignmentReceiptMonotonicMs']<o['deadlineMonotonicMs'];assert props[prefix+'outputDir']==str(actual)
