root,r=run('native-created-root-and-real-author-child',"export default defineNativeSuite({tests:[{title:'real output',run:(_,i)=>{assert(statSync(i.outputDir).isDirectory());assert.equal(i.outputPath(),i.outputDir);assert(!existsSync(i.outputPath('not-created','child.txt')));writeFileSync(i.outputPath('actual.txt'),'actual author bytes')}}]});");assert pathlib.Path(r['outputs'][0]['outputDir'],'actual.txt').read_text()=='actual author bytes'
root,r=run('lexical-bounds-create-no-foreign-paths',"export default defineNativeSuite({tests:[{title:'bounded output',run:(_,i)=>{for(const s of['..','../foreign','/tmp/foreign','a\\0b'])assert.throws(()=>i.outputPath(s));assert.throws(()=>i.outputPath(...Array(33).fill('x')));assert.throws(()=>i.outputPath('x'.repeat(4097)));assert.equal(i.outputPath('sub','..','safe'),i.outputDir+'/safe');assert(!existsSync(i.outputPath('safe')))}}]});")
root,r=run('all-hooks-real-associated-attempt-root',"let root;const check=(_,i)=>{assert(statSync(i.outputDir).isDirectory());if(root)assert.equal(i.outputDir,root);else root=i.outputDir};export default defineNativeSuite({hooks:{beforeAll:[{run:check}],beforeEach:[{run:check}],afterEach:[{run:check}],afterAll:[{run:check}]},tests:[{title:'hook output',run:check}]});");assert r['summary']['expected']==1
root,r=run('retry-gets-fresh-native-directory',"export default defineNativeSuite({tests:[{title:'real retries',retries:1,run:(_,i)=>{assert(!existsSync(i.outputPath('first.txt')));writeFileSync(i.outputPath('first.txt'),'retry'+i.retry);if(!i.retry)throw Error('actual first failure')}}]});");assert r['summary']['flaky']==1 and len(r['outputs'])==2 and [pathlib.Path(o['outputDir'],'first.txt').read_text()for o in r['outputs']]==['retry0','retry1']
root,r=run('nested-hooks-and-step-attachment-share-assignment',"const check=(_,i)=>assert(statSync(i.outputDir).isDirectory());export default defineNativeSuite({entries:[{title:'suite',hooks:{beforeAll:[{run:check}],beforeEach:[{run:check}],afterEach:[{run:check}],afterAll:[{run:check}]},entries:[{title:'nested output',run:async(_,i)=>{const file=i.outputPath('source.txt');writeFileSync(file,'real native attachment source');await i.step('actual copy',s=>s.attach('copied',{path:file}))}}]}]});");assert pathlib.Path(r['attachments'][0]['path']).read_text()=='real native attachment source'
root,r=run('serial-replay-uses-new-roots-for-each-actual-attempt',"export default defineNativeSuite({entries:[{title:'serial',mode:'serial',entries:[{title:'first',retries:1,run:(_,i)=>writeFileSync(i.outputPath('first.txt'),'actual retry'+i.retry)},{title:'second',retries:1,run:(_,i)=>{if(!i.retry)throw Error('actual group retry')}}]}]});");assert len(r['outputs'])==4 and len({o['generation']for o in r['outputs']})==4 and r['summary']['unexpected']==0
parallel=out/'parallel-owner-paths';source="const root="+json.dumps(str(parallel))+";const run=async(_,i)=>{writeFileSync(i.outputPath('actual.txt'),i.project.name);writeFileSync(root+'/'+i.project.name,i.outputDir);while(!existsSync(root+'/'+(i.project.name==='left'?'right':'left')))await wait(1);assert.notEqual(readFileSync(root+'/left','utf8'),readFileSync(root+'/right','utf8'))};export default defineNativeSuite({projects:[{name:'left',tests:[{title:'left',run}]},{name:'right',tests:[{title:'right',run}]}]});";root,r=run('parallel-owner-paths',source,workers=2);assert len({o['workerIndex']for o in r['outputs']})==2 and len({o['id']for o in r['outputs']})==2 and len({o['generation']for o in r['outputs']})==2
root,r=run('native-original-test-timeout-and-real-cleanup',"let cleaned=false;export default defineNativeSuite({hooks:{afterEach:[{run:(_,i)=>{assert(cleaned);assert(statSync(i.outputDir).isDirectory());assert.equal(i.status,'timedOut')}}]},tests:[{title:'actual timeout',timeout:80,run:async(_,i)=>{await new Promise(r=>i.signal.addEventListener('abort',r,{once:true}));cleaned=true}}]});",1);assert r['attempts'][0]['status']=='timedOut'and not r['attempts'][0]['expected']
